// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address attacker) public {
        if (attacker == address(0)) attacker = address(1);

        address initialOwner = c.owner();

        vm.deal(attacker, 1 ether);

        vm.prank(attacker);
        bool ok;
        try c.transferOwnership(attacker) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == initialOwner);
    }
}
